        negative = True
    if '(' in s and ')' in s:
        negative = True
    if '-' in s:
        negative = True
    # Remove tokens C1, C2
    s = re.sub(r'\bC1\b', '', s, flags=re.I)
    s = re.sub(r'\bC2\b', '', s, flags=re.I)
