    s = s.replace('(', '').replace(')', '')
    # Keep only digits, comma, dot, spaces? remove letters and spaces
    # Remove letters
    s = re.sub(r'[a-zA-Z]', '', s)
    # Remove spaces
    s = re.sub(r'\s+', '', s)
