    # Find separators
    commas = [m.start() for m in re.finditer(r',', s)]
    dots = [m.start() for m in re.finditer(r'\.', s)]
    # Apply last-separator rule
    if len(commas) > 0 and len(dots) > 0:
        # Both present; use last one as decimal
        if commas[-1] > dots[-1]:
            # comma is last -> comma is decimal
            # decimal is comma: remove dots as thousand? and replace comma with dot
            s_work = s.replace('.', '')
            s_work = s_work.replace(',', '.')
        else:
            # dot is last -> dot is decimal
