    elif len(commas) > 0 and len(dots) == 0:
        # Only commas
        if len(commas) == 1:
            # Check if exactly two digits follow
            pos = commas[0]
            if len(s) - pos - 1 == 2:
                # treat as decimal
                s_work = s.replace(',', '.')
            else:
                # treat as thousand sep -> remove
                s_work = s.replace(',', '')
        else:
            # multiple commas: last is decimal if 2 digits follow? typical
            pos = commas[-1]
            if len(s) - pos - 1 == 2:
                s_work = s.replace(',', '.')
            else:
                s_work = s.replace(',', '')
    elif len(dots) > 0 and len(commas) == 0:
        if len(dots) == 1:
            if len(s) - dots[0] - 1 == 2:
                s_work = s
            else:
                s_work = s.replace('.', '')
        else:
            pos = dots[-1]
            if len(s) - pos - 1 == 2:
                s_work = s.replace('.', '')
            else:
                s_work = s.replace('.', '')
    else:
        s_work = s
    # Try to parse
    try:
        val = float(s_work) if s_work else float('nan')
    except:
        try:
            val = float(re.sub(r'[^0-9\.]', '', s_work)) if s_work else float('nan')
        except:
