import re

def parse_notes(s):
    if s is None:
        s = ''
    s = str(s)
    res = {'items': None, 'adj_pct': 0.0, 'fee': 0.0, 'waive': False}
    # items from items=<int>
    m = re.search(r'items\s*=\s*(-?\d+)', s, flags=re.I)
    if m:
        try:
            res['items'] = int(m.group(1))
        except:
            res['items'] = None
    # adj_pct from adj=<signed number>%
    m = re.search(r'adj\s*=\s*([+-]?[\d\.]+)\s*%', s, flags=re.I)
    if m:
        try:
            res['adj_pct'] = float(m.group(1)) / 100.0 if m.group(1) else 0.0
        except:
            res['adj_pct'] = 0.0
    else:
        # maybe just number without % in some cases? probably not as per format
        pass
    # fee
    m = re.search(r'fee\s*=\s*([+-]?[\d\.]+)', s, flags=re.I)
    if m:
        try:
            res['fee'] = float(m.group(1))
        except:
            res['fee'] = 0.0
    # waive
    if re.search(r'waive\s*=\s*true', s, flags=re.I):
        res['waive'] = True
    else:
        res['waive'] = False
    return res
